<template><Card><h2>{{applications?'商户申请审核':'商户管理'}}</h2><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><template v-if="applications"><Select v-model="kind" clearable placeholder="全部申请类型" style="width:170px"><Option v-for="item in ['ADMISSION','PROFILE_CHANGE','QUALIFICATION_CHANGE']" :key="item" :value="item">{{label(item)}}</Option></Select><Select v-model="status" clearable placeholder="全部状态" style="width:150px"><Option v-for="item in ['DRAFT','SUBMITTED','APPROVED','REJECTED']" :key="item" :value="item">{{label(item)}}</Option></Select></template><Button @click="page=1;reload()">刷新查询</Button></div><Table :columns="columns" :data="records" :loading="loading" no-data-text="暂无记录"><template slot="state" slot-scope="{row}">{{label(row.status||row.state)}}</template><template slot="kind" slot-scope="{row}">{{label(row.kind)}}</template><template slot="action" slot-scope="{row}"><Button size="small" @click="open(row)">查看详情</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" :title="applications?'申请详情与版本':'商户资料'" width="80" :mask-closable="!busy"><template v-if="selected"><div v-if="applications&&selected.status==='SUBMITTED'&&can('admission.review')" class="s1-toolbar"><Button type="primary" :disabled="busy||pending" @click="review(true)">批准当前提交版本</Button><Button type="error" :disabled="busy||pending" @click="review(false)">驳回并填写原因</Button></div><div v-if="!applications&&can('store.supervise')" class="s1-toolbar"><Button :disabled="busy||pending" :type="selected.state==='CLOSED'?'primary':'error'" @click="supervise">{{selected.state==='CLOSED'?'恢复店铺':'关闭店铺'}}</Button></div><EligibilityCard v-if="eligibility" :value="eligibility"/><RecordDetail :value="selected" @preview="preview"/><section v-if="!applications&&can('admission.review')"><h3>资质监管</h3><div v-for="q in qualificationVersions" :key="q.id"><span>{{q.type}} · {{label(q.status)}} · 版本 {{q.revision}} </span><Button v-if="q.status!=='REVOKED'" size="small" :disabled="busy||pending" @click="revoke(q)">撤销资质</Button></div></section></template></Drawer></Card></template>
<script>import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import RecordDetail from './RecordDetail';import EligibilityCard from './EligibilityCard';export default {mixins:[pageMixin],components:{StatusPanel,RecordDetail,EligibilityCard},data:()=>({kind:'',status:'SUBMITTED',show:false,eligibility:null}),computed:{applications(){return this.$route.name==='s1-applications';},columns(){return [{title:'店铺名称',key:'storeName'},{title:'编号',key:'id',minWidth:180},...(this.applications?[{title:'申请类型',slot:'kind'}]:[]),{title:'状态',slot:'state'},{title:'数据版本',key:'version',width:100},{title:'操作',slot:'action',width:120}];},qualificationVersions(){return this.selected&&this.selected.qualifications&&this.selected.qualifications.versions||[];}},watch:{'$route'(){this.enterRoute();}},mounted(){this.enterRoute();},methods:{enterRoute(){this.show=false;this.page=1;this.reload();const id=this.$route.query.targetStore;if(!this.applications&&typeof id==='string'&&/^\d{1,19}$/.test(id))this.open({id});},reload(){return this.load(this.applications?'/applications':'/stores',this.applications?{kind:this.kind||undefined,status:this.status||undefined}:{});},async open(row){this.show=true;this.selected=null;this.eligibility=null;try{this.selected=await s1Read((this.applications?'/applications/':'/stores/')+row.id);if(!this.applications)this.eligibility=await s1Read('/stores/'+row.id+'/eligibility');}catch(e){this.error=e.message;}},async review(approve){const row=this.selected;const result=await this.reasonAction('/applications/'+row.id+(approve?'/approve':'/reject'),approve?'确认批准此提交版本':'驳回此提交版本',{expectedVersion:row.version,revision:row.revision});if(result){await this.open(row);await this.reload();}},async supervise(){const row=this.selected;const result=await this.reasonAction('/stores/'+row.id+(row.state==='CLOSED'?'/reopen':'/close'),row.state==='CLOSED'?'恢复店铺':'关闭店铺将即时失效经营资格',{expectedVersion:row.version});if(result){await this.open(row);await this.reload();}},async revoke(q){const result=await this.reasonAction('/qualifications/'+q.id+'/revoke','撤销当前资质并重新计算资格',{expectedVersion:q.version});if(result)await this.open(this.selected);}}};</script>
<style scoped>.s1-toolbar{display:flex;gap:12px;margin:18px 0}.ivu-page{margin-top:18px}h2,h3{margin-bottom:16px}section>div{padding:10px 0}</style>
